def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Infer the repeating stripe at each row's right-hand end.  When the
    # ending fragment is ambiguous, prefer the shortest period that best fits
    # a short suffix (allowing a single disrupted cell in a stripe).
    for r, row in enumerate(grid):
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        if last < 0 or last == w - 1:
            continue
        lo = max(0, last - 9)
        best = None
        for p in range(1, min(8, last + 1) + 1):
            n = last - lo + 1
            if n < p * 2:
                continue
            errors = sum(row[c] != row[c-p] for c in range(lo+p, last+1))
            score = errors / (n-p)
            cand = (score, p, errors)
            if best is None or cand < best:
                best = cand
        if best is None:
            continue
        _, p, errors = best
        # Require clear periodic evidence; a uniform run is the period-1 case.
        if errors > max(1, (last-lo+1-p)//4):
            continue
        for c in range(last + 1, w):
            if row[c-p] != bg:
                out[r][c] = 1
    return out

